import{_ as n,H as a,f as p,i as l}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"23｜化零为整：Plugins 插件打包与分发","description":"","frontmatter":{},"headers":[{"level":2,"title":"理解插件：Claude Code 的“应用商店“","slug":"理解插件-claude-code-的-应用商店","link":"#理解插件-claude-code-的-应用商店","children":[]},{"level":2,"title":"插件的目录结构","slug":"插件的目录结构","link":"#插件的目录结构","children":[]},{"level":2,"title":"plugin.json：插件的身份证","slug":"plugin-json-插件的身份证","link":"#plugin-json-插件的身份证","children":[]},{"level":2,"title":"添加斜杠命令","slug":"添加斜杠命令","link":"#添加斜杠命令","children":[]},{"level":2,"title":"添加子代理","slug":"添加子代理","link":"#添加子代理","children":[]},{"level":2,"title":"添加 Skills","slug":"添加-skills","link":"#添加-skills","children":[]},{"level":2,"title":"添加 Hooks","slug":"添加-hooks","link":"#添加-hooks","children":[]},{"level":2,"title":"添加 MCP 服务器","slug":"添加-mcp-服务器","link":"#添加-mcp-服务器","children":[]},{"level":2,"title":"实战项目：团队能力包","slug":"实战项目-团队能力包","link":"#实战项目-团队能力包","children":[]},{"level":2,"title":"发布与分发","slug":"发布与分发","link":"#发布与分发","children":[]},{"level":2,"title":"创建私有市场","slug":"创建私有市场","link":"#创建私有市场","children":[]},{"level":2,"title":"Plugins最佳实践","slug":"plugins最佳实践","link":"#plugins最佳实践","children":[]},{"level":2,"title":"总结一下","slug":"总结一下","link":"#总结一下","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"课程总结：从使用者到驾驭者","slug":"课程总结-从使用者到驾驭者","link":"#课程总结-从使用者到驾驭者","children":[]}],"relativePath":"ClaudeCode工程化实战/23｜化零为整：Plugins插件打包与分发.md","filePath":"ClaudeCode工程化实战/23｜化零为整：Plugins插件打包与分发.md","lastUpdated":1779815462000}'),e={name:"ClaudeCode工程化实战/23｜化零为整：Plugins插件打包与分发.md"};function i(t,s,o,c,d,u){return a(),p("div",null,[...s[0]||(s[0]=[l(`<h1 id="_23-化零为整-plugins-插件打包与分发" tabindex="-1">23｜化零为整：Plugins 插件打包与分发 <a class="header-anchor" href="#_23-化零为整-plugins-插件打包与分发" aria-label="Permalink to &quot;23｜化零为整：Plugins 插件打包与分发&quot;">​</a></h1><blockquote><p>释题：化零为整。把散落各处的 Commands、Skills、Agents、Hooks、MCP 配置打包成一个可安装、可升级、可分享的插件——项目“团队能力包”将完整演示这个过程。</p></blockquote><p>你好，我是黄佳。</p><p>至此你基本上已经掌握了 Claude Code 全局的方方面面。而上两讲我们又通过Agent SDK，先用 Python/TypeScript 代码驱动 Claude 执行任务，再深入探索了多轮对话和流式处理等高级模式。此时此刻，你已经掌握了从交互式使用到代码驱动的全部能力。</p><p>最后，还剩下一个问题我们还没有回答， <strong>这些能力怎么传递给别人？</strong>（课程群用户也提到了工作场景中这类困惑“我项目很多同事在维护， 一人好几个 Skill，工作流除了他们自己知道怎么用，别人都不知道”。）</p><p>你写了一个好用的 <code>/review</code> 命令，同事想用，你说“把这个文件复制到 <code>.claude/commands/</code> 下面”。你配了一个安全扫描代理，新人想用，你说“把 <code>agents/</code> 目录拷过去，然后再配一下 MCP 服务器”。你设了一套 Hooks 自动格式化，团队想统一，你说“把 <code>settings.json</code> 里的 hooks 配置合并进去”。</p><p>一个两个还行，十个八个就乱了。文件散落在各处，版本无法追踪，配置因人而异。 <strong>你从独行侠变成了布道者，但效率反而更低了。</strong> 这就是本讲要解决的问题。插件系统让你把所有的工具、命令、配置、规范打包成一个整体。新人入职时，只需要一条命令：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plugin install &amp;#64;our-company/dev-toolkit</span></span></code></pre></div><p>数据库连接、测试命令、代码审查规范、Git 工作流全部就位。 <strong>30 分钟的入职培训变成了 30 秒的安装命令。</strong></p><p>这就是插件的终极价值， <strong>把知识变成资产，把重复变成复用，把个人经验变成团队能力。</strong></p><h2 id="理解插件-claude-code-的-应用商店" tabindex="-1">理解插件：Claude Code 的“应用商店“ <a class="header-anchor" href="#理解插件-claude-code-的-应用商店" aria-label="Permalink to &quot;理解插件：Claude Code 的“应用商店“&quot;">​</a></h2><p>如果说 Claude Code 是一把瑞士军刀，那么 <strong>插件就是可以插拔的工具模块</strong>。插件是一种轻量级的打包和分享方式，可以组合斜杠命令、子代理、MCP 服务器和 Hooks。你可以用一条命令安装插件，在终端和 VS Code 中都能使用。</p><p>一个插件可以包含以下五类组件，每一类我们在前面的课程中都已经深入学习过。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/2eee295269ca9f1d76a646d3yy46b23a.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/2eee295269ca9f1d76a646d3yy46b23a.jpg" alt="图片"></a></p><p>插件的价值不在于它引入了新的机制，而在于它提供了一个标准化的打包和分发方式。你在前 20 讲里学到的所有扩展能力，都可以通过插件系统组合、封装、传递给他人。</p><p>在没有插件之前，团队协作依赖的是文档、脚本和口耳相传。让我们对比一下这两种方式的差异。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/9e37ce8c4284b217a8b6962508ccd6b6.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/9e37ce8c4284b217a8b6962508ccd6b6.jpg" alt="图片"></a></p><p>手动配置的根本问题不是麻烦——麻烦只是表象。根本问题是 <strong>不一致</strong>。当 15 个人各自配置时，你得到的是 15 种微妙不同的开发环境。插件把“约定”变成了“约束”，从“应该这样做“变成“只能这样做”。</p><p>根据 <a href="https://claude-plugins.dev/" target="_blank" rel="noreferrer">Claude Plugins 社区</a> 的统计，目前已有超过 10,000 个插件和 50,000 个 Agent Skills 可供使用。插件来源包括三个层级。</p><ol><li><p><strong>官方市场</strong>：Anthropic 维护的 <a href="https://github.com/anthropics/claude-plugins-official" target="_blank" rel="noreferrer">claude-plugins-official</a></p></li><li><p><strong>社区市场</strong>：开发者贡献的公开插件</p></li><li><p><strong>企业市场</strong>：公司内部的私有插件</p></li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/907ac6b2a120cfe25d959a3933eaf851.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/907ac6b2a120cfe25d959a3933eaf851.png" alt="图片"></a></p><p>有人说，Claude Code 的插件市场就像是 AI 辅助开发工作流的 npm。去中心化的来源，任何人都可以托管市场，一条命令安装。这个类比非常精准。npm 改变了 JavaScript 生态的协作方式，让开发者不再重复造轮子。Claude Code 的插件系统正在对 AI 辅助开发做同样的事情，把个人的最佳实践变成社区的公共资产。</p><h2 id="插件的目录结构" tabindex="-1">插件的目录结构 <a class="header-anchor" href="#插件的目录结构" aria-label="Permalink to &quot;插件的目录结构&quot;">​</a></h2><p>根据 <a href="https://code.claude.com/docs/en/plugins" target="_blank" rel="noreferrer">官方文档</a>，插件的标准结构如下。理解这个结构是创建插件的第一步，因为 Claude Code 依赖固定的目录约定来发现和加载各类组件：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-plugin/</span></span>
<span class="line"><span>├── .claude-plugin/</span></span>
<span class="line"><span>│   └── plugin.json        # 插件元数据（必需）</span></span>
<span class="line"><span>├── commands/              # 斜杠命令（可选）</span></span>
<span class="line"><span>│   ├── review.md</span></span>
<span class="line"><span>│   └── deploy.md</span></span>
<span class="line"><span>├── agents/                # 子代理（可选）</span></span>
<span class="line"><span>│   ├── security-scanner.md</span></span>
<span class="line"><span>│   └── code-reviewer.md</span></span>
<span class="line"><span>├── skills/                # Agent Skills（可选）</span></span>
<span class="line"><span>│   └── react-patterns/</span></span>
<span class="line"><span>│       └── SKILL.md</span></span>
<span class="line"><span>├── hooks/                 # Hooks 配置（可选）</span></span>
<span class="line"><span>│   └── hooks.json</span></span>
<span class="line"><span>├── .mcp.json              # MCP 服务器配置（可选）</span></span>
<span class="line"><span>└── README.md              # 插件文档</span></span></code></pre></div><p><strong>咖哥发言</strong>：只有 <code>plugin.json</code> 放在 <code>.claude-plugin/</code> 目录内，其他所有目录（commands、agents、skills、hooks）都在插件根目录下。注意不要把 commands 等目录也放进 <code>.claude-plugin/</code> 里。</p><h2 id="plugin-json-插件的身份证" tabindex="-1">plugin.json：插件的身份证 <a class="header-anchor" href="#plugin-json-插件的身份证" aria-label="Permalink to &quot;plugin.json：插件的身份证&quot;">​</a></h2><p>每个插件必须有 <code>.claude-plugin/plugin.json</code> 文件。这个文件的作用类似于 npm 的 <code>package.json</code>——它定义了插件的身份、版本和描述信息，是 Claude Code 识别和管理插件的唯一入口：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;name&quot;: &quot;team-toolkit&quot;,</span></span>
<span class="line"><span>  &quot;version&quot;: &quot;1.0.0&quot;,</span></span>
<span class="line"><span>  &quot;description&quot;: &quot;团队标准开发工具包：代码审查、测试、部署一体化&quot;,</span></span>
<span class="line"><span>  &quot;author&quot;: &quot;DevOps Team&quot;,</span></span>
<span class="line"><span>  &quot;repository&quot;: &quot;https://github.com/our-company/team-toolkit&quot;,</span></span>
<span class="line"><span>  &quot;license&quot;: &quot;MIT&quot;,</span></span>
<span class="line"><span>  &quot;keywords&quot;: [&quot;team&quot;, &quot;devops&quot;, &quot;workflow&quot;, &quot;code-review&quot;]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>各字段的含义和说明如下表。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/5fdd8f7bb2ed001a0ae21aa68da77078.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/5fdd8f7bb2ed001a0ae21aa68da77078.jpg" alt="图片"></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/6885a58422265398d439f7b081505d7f.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/6885a58422265398d439f7b081505d7f.jpg" alt="图片"></a></p><h2 id="添加斜杠命令" tabindex="-1">添加斜杠命令 <a class="header-anchor" href="#添加斜杠命令" aria-label="Permalink to &quot;添加斜杠命令&quot;">​</a></h2><p>命令是插件中用户感知最直接的组件。在 <code>commands/</code> 目录下创建 Markdown 文件，文件名（不含 <code>.md</code>）即为命令名。命令文件的格式与我们在 <a href="https://time.geekbang.org/column/article/946297" target="_blank" rel="noreferrer">第 10 讲</a> 中学习的 Slash Commands 完全一致，frontmatter 定义元数据，正文定义行为指令。</p><p><strong>commands/review.md</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: review</span></span>
<span class="line"><span>description: 对当前文件或目录进行代码审查</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>当用户运行 \`/review [target]\` 时，执行代码审查。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 审查流程</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 如果指定了 target，审查该文件或目录</span></span>
<span class="line"><span>2. 如果没有指定，审查当前打开的文件</span></span>
<span class="line"><span>3. 如果没有上下文，询问用户</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 审查要点</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 代码质量：命名规范、DRY 原则、复杂度</span></span>
<span class="line"><span>- 潜在 Bug：边界条件、空值处理、类型错误</span></span>
<span class="line"><span>- 安全问题：输入验证、敏感数据、注入风险</span></span>
<span class="line"><span>- 性能问题：不必要的循环、内存泄漏</span></span>
<span class="line"><span>- 最佳实践：框架惯例、设计模式</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 输出格式</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`markdown</span></span>
<span class="line"><span>## 代码审查报告</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**文件**: {file_path}</span></span>
<span class="line"><span>**审查时间**: {timestamp}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 发现的问题</span></span>
<span class="line"><span></span></span>
<span class="line"><span>🔴 **严重** (必须修复)</span></span>
<span class="line"><span>- [问题描述] (行号)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>🟡 **警告** (建议修复)</span></span>
<span class="line"><span>- [问题描述] (行号)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>🔵 **建议** (可选改进)</span></span>
<span class="line"><span>- [问题描述] (行号)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 总结</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[1-2 句总结]</span></span></code></pre></div><p>安装插件后，命令会带上插件名称作为 <strong>命名空间</strong>，避免不同插件的命令冲突。这个机制与编程语言中的模块命名空间是同一个思路。</p><ul><li><p>插件名： <code>team-toolkit</code></p></li><li><p>命令文件： <code>commands/review.md</code></p></li><li><p>实际命令： <code>/team-toolkit:review</code></p></li></ul><p>如果只有一个命令或命令名唯一，也可以直接用 <code>/review</code>。Claude Code 会自动解析，优先匹配唯一命令名。</p><p>命令可以接受 <strong>参数</strong>，使用 <code>$ARGUMENTS</code> 占位符接收用户输入。在 Markdown 中说明参数格式，让 Claude 知道如何解析。下面这个 TODO 命令展示了如何设计一个支持优先级和指派人的参数化命令：</p><p><strong>commands/todo.md</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: todo</span></span>
<span class="line"><span>description: 添加 TODO 注释，支持优先级和指派人</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>用法：\`/todo [优先级] [消息] [@指派人]\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 参数</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- \`优先级\`（可选）：</span></span>
<span class="line"><span>  - \`!\` 或 \`high\` → 高优先级</span></span>
<span class="line"><span>  - \`?\` 或 \`discuss\` → 待讨论</span></span>
<span class="line"><span>  - 默认 → 普通优先级</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- \`消息\`：TODO 的内容</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- \`@指派人\`（可选）：指定负责人</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 示例</span></span>
<span class="line"><span>/todo 修复登录验证 → // TODO: 修复登录验证</span></span>
<span class="line"><span>/todo ! 紧急修复安全漏洞 → // TODO [HIGH]: 紧急修复安全漏洞</span></span>
<span class="line"><span>/todo ? 是否需要缓存 @john → // TODO [DISCUSS @john]: 是否需要缓存</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 行为</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 自动检测当前文件的语言，使用正确的注释格式</span></span>
<span class="line"><span>2. 插入到光标位置或相关代码附近</span></span>
<span class="line"><span>3. 如果没有文件上下文，询问位置</span></span></code></pre></div><h2 id="添加子代理" tabindex="-1">添加子代理 <a class="header-anchor" href="#添加子代理" aria-label="Permalink to &quot;添加子代理&quot;">​</a></h2><p>子代理是插件中的“专业助手”。在 <code>agents/</code> 目录下创建 Markdown 文件，每个文件定义一个具有特定职责、工具权限和行为准则的代理。这与我们在第 3-8 讲学习的子代理概念完全一致，区别在于现在它被打包进了插件，可以随插件一起安装和分发。</p><p>下面是一个安全扫描代理的完整定义。注意它只使用了 Read、Grep、Glob 三个只读工具——遵循我们在第 4 讲强调的最小权限原则。</p><p><strong>agents/security-scanner.md</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: security-scanner</span></span>
<span class="line"><span>description: 扫描代码中的安全漏洞</span></span>
<span class="line"><span>tools: Read, Grep, Glob</span></span>
<span class="line"><span>model: sonnet</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>你是一个安全专家，专门识别代码中的安全漏洞。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 扫描范围</span></span>
<span class="line"><span></span></span>
<span class="line"><span>重点检查：</span></span>
<span class="line"><span>1. **注入漏洞**：SQL 注入、命令注入、XSS</span></span>
<span class="line"><span>2. **认证问题**：弱密码、硬编码凭证、会话管理</span></span>
<span class="line"><span>3. **数据暴露**：敏感信息日志、不安全传输</span></span>
<span class="line"><span>4. **访问控制**：权限检查、路径遍历</span></span>
<span class="line"><span>5. **依赖风险**：已知漏洞的依赖包</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 工作流程</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 使用 Glob 获取所有源代码文件</span></span>
<span class="line"><span>2. 使用 Grep 搜索可疑模式</span></span>
<span class="line"><span>3. 使用 Read 深入分析可疑代码</span></span>
<span class="line"><span>4. 生成结构化报告</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 输出格式</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`markdown</span></span>
<span class="line"><span># 安全扫描报告</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**扫描时间**: {timestamp}</span></span>
<span class="line"><span>**扫描范围**: {directory}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 发现的漏洞</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 🔴 高危 (立即修复)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#### [漏洞名称]</span></span>
<span class="line"><span>- **文件**: path/to/file.js:42</span></span>
<span class="line"><span>- **类型**: SQL Injection</span></span>
<span class="line"><span>- **描述**: [详细描述]</span></span>
<span class="line"><span>- **修复建议**: [具体建议]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 🟡 中危 (尽快修复)</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 🔵 低危 (建议修复)</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 统计</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 高危: X 个</span></span>
<span class="line"><span>- 中危: Y 个</span></span>
<span class="line"><span>- 低危: Z 个</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 注意事项</span></span>
<span class="line"><span>- 只报告有实际证据的问题，不要臆测</span></span>
<span class="line"><span>- 提供具体的修复建议，不只是指出问题</span></span>
<span class="line"><span>- 如果不确定是否是漏洞，标注为&quot;疑似&quot;</span></span></code></pre></div><p>代理的 frontmatter 支持以下配置字段。其中 <code>model</code> 字段值得特别关注，对于只做扫描和分析的代理，使用 sonnet 模型就够了；对于需要快速修复简单问题的代理，haiku 更合适，速度更快、成本更低。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/fdbcbf627f457ab68a5776a37c81364f.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/fdbcbf627f457ab68a5776a37c81364f.jpg" alt="图片"></a></p><p>与安全扫描代理不同，快速修复代理需要写入权限（Edit 工具），因为它的职责是直接修改代码。但它被严格限定在“小问题”范围内——拼写错误、缺失导入、简单语法错误。任何复杂的架构变更或安全问题都不在它的职责范围内，这是通过 prompt 中的明确边界来约束的。</p><p><strong>agents/quick-fix.md</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: quick-fix</span></span>
<span class="line"><span>description: 快速修复小问题：拼写错误、缺失导入、简单 bug</span></span>
<span class="line"><span>tools: Read, Edit, Grep, Glob</span></span>
<span class="line"><span>model: haiku</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>你是快速修复专家。你的任务是**又快又准**地修复小问题。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 你处理的问题</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 拼写错误</span></span>
<span class="line"><span>- 缺失的 import/require</span></span>
<span class="line"><span>- 简单语法错误</span></span>
<span class="line"><span>- 明显的空值检查遗漏</span></span>
<span class="line"><span>- 缺失的 return 语句</span></span>
<span class="line"><span>- Off-by-one 错误</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 你不处理的问题</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 架构变更</span></span>
<span class="line"><span>- 复杂重构</span></span>
<span class="line"><span>- 性能优化</span></span>
<span class="line"><span>- 安全问题（上报这些！）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 工作流程</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. **识别问题**：阅读错误信息或用户描述</span></span>
<span class="line"><span>2. **定位问题**：找到确切的位置</span></span>
<span class="line"><span>3. **最小修复**：只改必要的代码</span></span>
<span class="line"><span>4. **验证语法**：确保不引入新错误</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 输出格式</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\\`\`\`markdown</span></span>
<span class="line"><span>## 已修复</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**文件**: path/to/file.js</span></span>
<span class="line"><span>**行号**: 42</span></span>
<span class="line"><span>**问题**: 变量名拼写错误</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\\`\`\`diff</span></span>
<span class="line"><span>- const usrName = user.name;</span></span>
<span class="line"><span>+ const userName = user.name;</span></span>
<span class="line"><span>\\\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**完成。** 修正了变量名拼写。</span></span>
<span class="line"><span>\\\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 原则</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- **快**：不要过度解释</span></span>
<span class="line"><span>- **小**：最小化修改</span></span>
<span class="line"><span>- **诚实**：问题复杂就直说，不要硬修</span></span></code></pre></div><h2 id="添加-skills" tabindex="-1">添加 Skills <a class="header-anchor" href="#添加-skills" aria-label="Permalink to &quot;添加 Skills&quot;">​</a></h2><p>Skills 放在 <code>skills/</code> 目录下，每个 Skill 是一个子目录。这与我们在第 9-14 讲学习的 Skills 系统完全一致，包含一个 <code>SKILL.md</code> 主文件，以及可选的 <code>chapters/</code> 子目录用于渐进式披露。当 Skill 的知识量较大时，章节化结构可以避免一次性加载所有内容，节省上下文窗口。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>skills/</span></span>
<span class="line"><span>└── react-patterns/</span></span>
<span class="line"><span>    ├── SKILL.md           # 主文件</span></span>
<span class="line"><span>    └── chapters/          # 可选：分章节</span></span>
<span class="line"><span>        ├── hooks.md</span></span>
<span class="line"><span>        ├── context.md</span></span>
<span class="line"><span>        └── performance.md</span></span></code></pre></div><p>下面是一个 React 最佳实践 Skill 的示例。注意 <code>description</code> 字段的写法，它不是给人看的说明文档，而是给 Claude 看的触发器。当用户的请求与 description 中的关键词匹配时，Claude 会自动加载这个 Skill。</p><p><strong>skills/react-patterns/SKILL.md</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: React 最佳实践</span></span>
<span class="line"><span>description: React 组件设计模式、Hooks 使用指南、性能优化技巧</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span># React 最佳实践</span></span>
<span class="line"><span></span></span>
<span class="line"><span>本技能包含 React 开发的最佳实践，帮助你编写高质量的 React 代码。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 目录</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- [Hooks 使用指南](./chapters/hooks.md)</span></span>
<span class="line"><span>- [Context 最佳实践](./chapters/context.md)</span></span>
<span class="line"><span>- [性能优化](./chapters/performance.md)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 核心原则</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. **组件单一职责**：一个组件做一件事</span></span>
<span class="line"><span>2. **状态提升最小化**：状态放在需要它的最近公共祖先</span></span>
<span class="line"><span>3. **避免过早优化**：先让它工作，再让它快</span></span>
<span class="line"><span>4. **优先组合而非继承**：使用 children 和 render props</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 快速参考</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 自定义 Hook 命名</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`javascript</span></span>
<span class="line"><span>// 好的命名</span></span>
<span class="line"><span>useUser()</span></span>
<span class="line"><span>useLocalStorage()</span></span>
<span class="line"><span>useDebounce()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 不好的命名</span></span>
<span class="line"><span>fetchUser()      // 不是 use 开头</span></span>
<span class="line"><span>useData()        // 太模糊</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 组件文件结构</span></span>
<span class="line"><span>ComponentName/</span></span>
<span class="line"><span>├── index.ts           # 导出</span></span>
<span class="line"><span>├── ComponentName.tsx  # 组件实现</span></span>
<span class="line"><span>├── ComponentName.test.tsx</span></span>
<span class="line"><span>├── ComponentName.styles.ts</span></span>
<span class="line"><span>└── types.ts           # 类型定义</span></span></code></pre></div><h2 id="添加-hooks" tabindex="-1">添加 Hooks <a class="header-anchor" href="#添加-hooks" aria-label="Permalink to &quot;添加 Hooks&quot;">​</a></h2><p>Hooks 是插件中的自动触发器。在 <code>hooks/</code> 目录下创建 <code>hooks.json</code> 配置文件，定义在 Claude 执行工具前后自动运行的检查脚本。这与 Hooks 事件驱动机制（参考 <a href="https://time.geekbang.org/column/article/953022" target="_blank" rel="noreferrer">第 15 讲</a>）完全一致，只是现在它被封装在插件中，随插件安装自动生效。</p><p><strong>hooks/hooks.json</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;hooks&quot;: [</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>      &quot;event&quot;: &quot;PreToolUse&quot;,</span></span>
<span class="line"><span>      &quot;matcher&quot;: &quot;Bash&quot;,</span></span>
<span class="line"><span>      &quot;command&quot;: [&quot;bash&quot;, &quot;./hooks/check-bash.sh&quot;]</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>      &quot;event&quot;: &quot;PostToolUse&quot;,</span></span>
<span class="line"><span>      &quot;matcher&quot;: &quot;Write&quot;,</span></span>
<span class="line"><span>      &quot;command&quot;: [&quot;bash&quot;, &quot;./hooks/auto-format.sh&quot;]</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>      &quot;event&quot;: &quot;PostToolUse&quot;,</span></span>
<span class="line"><span>      &quot;matcher&quot;: &quot;Edit&quot;,</span></span>
<span class="line"><span>      &quot;command&quot;: [&quot;bash&quot;, &quot;./hooks/auto-format.sh&quot;]</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这个配置做了两件事，在每次 Bash 命令执行前检查是否包含危险模式（PreToolUse），在每次文件写入或编辑后自动格式化代码（PostToolUse）。</p><p>下面是两个 Hook 脚本的完整实现。第一个脚本是安全守门员，它从 stdin 读取 Claude 即将执行的 Bash 命令，与危险模式列表逐一比对，发现匹配就拒绝执行。这是一道看不见的防线，防止 Claude 在深夜加班时不小心执行了 <code>rm -rf /</code> 等危险命令。</p><p><strong>hooks/check-bash.sh</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span># 检查 Bash 命令是否安全</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 从 stdin 读取输入</span></span>
<span class="line"><span>INPUT=$(cat)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 提取命令</span></span>
<span class="line"><span>COMMAND=&amp;lt;!--§§MATH_0§§--&gt;INPUT&quot; | jq -r &#39;.tool_input.command // empty&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 危险模式列表</span></span>
<span class="line"><span>DANGEROUS_PATTERNS=(</span></span>
<span class="line"><span>    &quot;rm -rf /&quot;</span></span>
<span class="line"><span>    &quot;rm -rf ~&quot;</span></span>
<span class="line"><span>    &quot;sudo rm&quot;</span></span>
<span class="line"><span>    &quot;&gt; /dev/&quot;</span></span>
<span class="line"><span>    &quot;chmod 777&quot;</span></span>
<span class="line"><span>    &quot;curl.*|.*sh&quot;</span></span>
<span class="line"><span>    &quot;wget.*|.*sh&quot;</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 检查每个危险模式</span></span>
<span class="line"><span>for pattern in &quot;\${DANGEROUS_PATTERNS[@]}&quot;; do</span></span>
<span class="line"><span>    if echo &quot;&amp;lt;!--§§MATH_1§§--&gt;pattern&quot;; then</span></span>
<span class="line"><span>        # 输出拒绝决定</span></span>
<span class="line"><span>        cat &amp;lt;&amp;lt; EOF</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;decision&quot;: &quot;deny&quot;,</span></span>
<span class="line"><span>  &quot;reason&quot;: &quot;Blocked potentially dangerous command pattern: $pattern&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>EOF</span></span>
<span class="line"><span>        exit 0</span></span>
<span class="line"><span>    fi</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 允许执行</span></span>
<span class="line"><span>echo &#39;{&quot;decision&quot;: &quot;allow&quot;}&#39;</span></span></code></pre></div><p>第二个脚本是自动格式化器，它检测被写入文件的扩展名，自动调用对应的格式化工具。Python 文件用 black，JavaScript/TypeScript 用 prettier，Go 文件用 gofmt。这样团队成员不需要记住各种格式化命令，也不会因为忘记格式化而产生风格不一致的代码。</p><p><strong>hooks/auto-format.sh</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span># 文件写入后自动格式化</span></span>
<span class="line"><span></span></span>
<span class="line"><span>INPUT=$(cat)</span></span>
<span class="line"><span>FILE_PATH=&amp;lt;!--§§MATH_2§§--&gt;INPUT&quot; | jq -r &#39;.tool_input.file_path // empty&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if [ -z &quot;$FILE_PATH&quot; ]; then</span></span>
<span class="line"><span>    exit 0</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 根据文件类型格式化</span></span>
<span class="line"><span>case &quot;$FILE_PATH&quot; in</span></span>
<span class="line"><span>    *.py)</span></span>
<span class="line"><span>        if command -v black &amp;&gt; /dev/null; then</span></span>
<span class="line"><span>            black &quot;$FILE_PATH&quot; 2&gt;/dev/null</span></span>
<span class="line"><span>        fi</span></span>
<span class="line"><span>        ;;</span></span>
<span class="line"><span>    *.js|*.ts|*.jsx|*.tsx)</span></span>
<span class="line"><span>        if command -v prettier &amp;&gt; /dev/null; then</span></span>
<span class="line"><span>            prettier --write &quot;$FILE_PATH&quot; 2&gt;/dev/null</span></span>
<span class="line"><span>        fi</span></span>
<span class="line"><span>        ;;</span></span>
<span class="line"><span>    *.go)</span></span>
<span class="line"><span>        if command -v gofmt &amp;&gt; /dev/null; then</span></span>
<span class="line"><span>            gofmt -w &quot;$FILE_PATH&quot; 2&gt;/dev/null</span></span>
<span class="line"><span>        fi</span></span>
<span class="line"><span>        ;;</span></span>
<span class="line"><span>esac</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &#39;{&quot;decision&quot;: &quot;allow&quot;}&#39;</span></span></code></pre></div><h2 id="添加-mcp-服务器" tabindex="-1">添加 MCP 服务器 <a class="header-anchor" href="#添加-mcp-服务器" aria-label="Permalink to &quot;添加 MCP 服务器&quot;">​</a></h2><p>MCP（Model Context Protocol）是插件中最强大也最敏感的组件。它让 Claude 能够连接数据库、调用 API、访问文件系统等外部资源。在插件根目录创建 <code>.mcp.json</code> 文件来配置 MCP 服务器。</p><p><strong>.mcp.json</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;mcpServers&quot;: {</span></span>
<span class="line"><span>    &quot;postgres&quot;: {</span></span>
<span class="line"><span>      &quot;command&quot;: &quot;npx&quot;,</span></span>
<span class="line"><span>      &quot;args&quot;: [&quot;-y&quot;, &quot;@anthropic/mcp-server-postgres&quot;],</span></span>
<span class="line"><span>      &quot;env&quot;: {</span></span>
<span class="line"><span>        &quot;DATABASE_URL&quot;: &quot;\${DATABASE_URL}&quot;</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    &quot;github&quot;: {</span></span>
<span class="line"><span>      &quot;command&quot;: &quot;npx&quot;,</span></span>
<span class="line"><span>      &quot;args&quot;: [&quot;-y&quot;, &quot;@anthropic/mcp-server-github&quot;],</span></span>
<span class="line"><span>      &quot;env&quot;: {</span></span>
<span class="line"><span>        &quot;GITHUB_TOKEN&quot;: &quot;\${GITHUB_TOKEN}&quot;</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    &quot;filesystem&quot;: {</span></span>
<span class="line"><span>      &quot;command&quot;: &quot;npx&quot;,</span></span>
<span class="line"><span>      &quot;args&quot;: [&quot;-y&quot;, &quot;@anthropic/mcp-server-filesystem&quot;],</span></span>
<span class="line"><span>      &quot;env&quot;: {</span></span>
<span class="line"><span>        &quot;ALLOWED_PATHS&quot;: &quot;\${HOME}/projects&quot;</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>MCP 配置中可以使用 <code>\${VAR_NAME}</code> 引用环境变量。这是一个关键的设计决策——不要在配置文件中硬编码数据库密码或 API Token。用户安装插件后，需要在自己的环境中设置这些变量：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>export DATABASE_URL=&quot;postgres://user:pass@localhost/db&quot;</span></span>
<span class="line"><span>export GITHUB_TOKEN=&quot;ghp_xxxxxxxxxxxx&quot;</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/43aa3c1a1784259a99976565b3b7985c.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/43aa3c1a1784259a99976565b3b7985c.jpg" alt="图片"></a></p><p>&gt; 一个简单的判断标准：如果你不敢把 <code>.mcp.json</code> 里的连接信息发到公开频道，那说明这个配置有泄露风险，需要改用环境变量。</p><h2 id="实战项目-团队能力包" tabindex="-1">实战项目：团队能力包 <a class="header-anchor" href="#实战项目-团队能力包" aria-label="Permalink to &quot;实战项目：团队能力包&quot;">​</a></h2><p>前面我们逐一介绍了插件的各个组件。现在，让我们把它们组合在一起，构建一个完整的团队能力包插件。</p><p>项目背景是假设你在一个使用以下技术栈的团队：</p><ul><li><p><strong>前端</strong>：React + TypeScript</p></li><li><p><strong>后端</strong>：Node.js + PostgreSQL</p></li><li><p><strong>测试</strong>：Jest + Cypress</p></li><li><p><strong>部署</strong>：Docker + Kubernetes</p></li></ul><p>你要创建一个插件，包含代码审查命令、测试运行命令、部署命令、安全扫描代理、快速修复代理、React 最佳实践 Skill、安全检查 Hook，以及数据库查询 MCP。这些组件覆盖了开发流程的各个环节——从编码到审查，从测试到部署，从安全到知识沉淀。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/e51c04415024f2df4799bc27b9d88b6e.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/e51c04415024f2df4799bc27b9d88b6e.png" alt="图片"></a></p><p>下面是这个团队能力包的完整目录树。每个文件的内容我们在前面的章节中都已经详细介绍过，这里把它们按照插件规范组织在一起。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>team-toolkit/</span></span>
<span class="line"><span>├── .claude-plugin/</span></span>
<span class="line"><span>│   └── plugin.json</span></span>
<span class="line"><span>├── commands/</span></span>
<span class="line"><span>│   ├── review.md</span></span>
<span class="line"><span>│   ├── test.md</span></span>
<span class="line"><span>│   └── deploy.md</span></span>
<span class="line"><span>├── agents/</span></span>
<span class="line"><span>│   ├── security-scanner.md</span></span>
<span class="line"><span>│   └── quick-fix.md</span></span>
<span class="line"><span>├── skills/</span></span>
<span class="line"><span>│   └── react-patterns/</span></span>
<span class="line"><span>│       ├── SKILL.md</span></span>
<span class="line"><span>│       └── chapters/</span></span>
<span class="line"><span>│           ├── hooks.md</span></span>
<span class="line"><span>│           ├── context.md</span></span>
<span class="line"><span>│           └── performance.md</span></span>
<span class="line"><span>├── hooks/</span></span>
<span class="line"><span>│   ├── hooks.json</span></span>
<span class="line"><span>│   ├── check-bash.sh</span></span>
<span class="line"><span>│   └── auto-format.sh</span></span>
<span class="line"><span>├── .mcp.json</span></span>
<span class="line"><span>└── README.md</span></span></code></pre></div><p><strong>plugin.json</strong></p><p>团队能力包的 plugin.json 如下</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;name&quot;: &quot;team-toolkit&quot;,</span></span>
<span class="line"><span>  &quot;version&quot;: &quot;2.0.0&quot;,</span></span>
<span class="line"><span>  &quot;description&quot;: &quot;团队标准开发工具包：代码审查、测试、部署、安全扫描一体化&quot;,</span></span>
<span class="line"><span>  &quot;author&quot;: &quot;Platform Team&quot;,</span></span>
<span class="line"><span>  &quot;repository&quot;: &quot;https://github.com/our-company/team-toolkit&quot;,</span></span>
<span class="line"><span>  &quot;license&quot;: &quot;MIT&quot;,</span></span>
<span class="line"><span>  &quot;keywords&quot;: [</span></span>
<span class="line"><span>    &quot;team&quot;,</span></span>
<span class="line"><span>    &quot;devops&quot;,</span></span>
<span class="line"><span>    &quot;code-review&quot;,</span></span>
<span class="line"><span>    &quot;testing&quot;,</span></span>
<span class="line"><span>    &quot;deployment&quot;,</span></span>
<span class="line"><span>    &quot;security&quot;</span></span>
<span class="line"><span>  ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>代码审查命令</strong></p><p>这是团队能力包中最常用的命令。它不仅检查代码质量，还覆盖了 TypeScript 类型安全、React 特定规范和安全问题。审查报告的结构化输出让团队成员能快速定位和修复问题。</p><p><strong>commands/review.md</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: review</span></span>
<span class="line"><span>description: 对代码进行全面审查，输出结构化报告</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>当用户运行 \`/review [target]\` 时，执行代码审查。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 审查维度</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. **代码质量**</span></span>
<span class="line"><span>   - 命名规范（camelCase/PascalCase）</span></span>
<span class="line"><span>   - DRY 原则（重复代码）</span></span>
<span class="line"><span>   - 函数长度（建议 &amp;lt; 30 行）</span></span>
<span class="line"><span>   - 圈复杂度（建议 &amp;lt; 10）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. **TypeScript 特定**</span></span>
<span class="line"><span>   - 类型安全（避免 any）</span></span>
<span class="line"><span>   - 空值处理（可选链、空值合并）</span></span>
<span class="line"><span>   - 接口设计</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. **React 特定**</span></span>
<span class="line"><span>   - Hooks 规则</span></span>
<span class="line"><span>   - 组件拆分</span></span>
<span class="line"><span>   - 状态管理</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. **安全**</span></span>
<span class="line"><span>   - 输入验证</span></span>
<span class="line"><span>   - XSS 防护</span></span>
<span class="line"><span>   - 敏感数据处理</span></span>
<span class="line"><span></span></span>
<span class="line"><span>5. **测试**</span></span>
<span class="line"><span>   - 测试覆盖率</span></span>
<span class="line"><span>   - 边界条件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 输出格式</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\\`\`\`markdown</span></span>
<span class="line"><span># 代码审查报告</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**目标**: {target}</span></span>
<span class="line"><span>**时间**: {timestamp}</span></span>
<span class="line"><span>**审查者**: Claude (team-toolkit v2.0.0)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 总览</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| 类别 | 发现 | 严重性 |</span></span>
<span class="line"><span>|------|------|--------|</span></span>
<span class="line"><span>| 代码质量 | X | 中 |</span></span>
<span class="line"><span>| 安全 | Y | 高 |</span></span>
<span class="line"><span>| 性能 | Z | 低 |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 必须修复</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### [问题标题]</span></span>
<span class="line"><span>**文件**: path/to/file.ts:42</span></span>
<span class="line"><span>**类型**: 安全漏洞</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**问题**:</span></span>
<span class="line"><span>[详细描述]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**修复建议**:</span></span>
<span class="line"><span>\\\`\`\`typescript</span></span>
<span class="line"><span>// 建议的修复代码</span></span>
<span class="line"><span>\\\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 建议修复</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 可选改进</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 亮点</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[做得好的地方]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>*由 team-toolkit 生成*</span></span>
<span class="line"><span>\\\`\`\`</span></span></code></pre></div><p><strong>测试命令</strong></p><p>测试命令不只是运行测试，它还会分析失败原因，判断是代码 bug 还是测试过时，并提供具体的修复建议。这个命令的 <code>--fix</code> 选项让 Claude 尝试自动修复失败的测试，把“发现问题”和“解决问题”合二为一。</p><p><strong>commands/test.md</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: test</span></span>
<span class="line"><span>description: 运行测试并分析结果，失败时提供修复建议</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>用法：\`/test [scope] [options]\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 参数</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- \`scope\`（可选）：</span></span>
<span class="line"><span>  - \`unit\` - 只运行单元测试</span></span>
<span class="line"><span>  - \`e2e\` - 只运行端到端测试</span></span>
<span class="line"><span>  - \`all\` - 运行全部（默认）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- \`options\`：</span></span>
<span class="line"><span>  - \`--fix\` - 尝试自动修复失败的测试</span></span>
<span class="line"><span>  - \`--coverage\` - 生成覆盖率报告</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 工作流程</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 运行指定范围的测试</span></span>
<span class="line"><span>2. 收集测试结果</span></span>
<span class="line"><span>3. 对失败的测试：</span></span>
<span class="line"><span>   - 分析失败原因</span></span>
<span class="line"><span>   - 检查是代码 bug 还是测试过时</span></span>
<span class="line"><span>   - 提供修复建议</span></span>
<span class="line"><span>4. 如果指定了 --fix，尝试自动修复</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 输出格式</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\\`\`\`markdown</span></span>
<span class="line"><span># 测试报告</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 结果</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| 指标 | 值 |</span></span>
<span class="line"><span>|------|------|</span></span>
<span class="line"><span>| 总计 | 150 |</span></span>
<span class="line"><span>| 通过 | 147 |</span></span>
<span class="line"><span>| 失败 | 3 |</span></span>
<span class="line"><span>| 跳过 | 0 |</span></span>
<span class="line"><span>| 覆盖率 | 85% |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 失败的测试</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### test_user_creation</span></span>
<span class="line"><span>**文件**: tests/user.test.ts:42</span></span>
<span class="line"><span>**错误**: AssertionError: expected &#39;active&#39; but got &#39;pending&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**分析**: User 模型的默认状态在 commit abc123 中从 &#39;active&#39; 改为 &#39;pending&#39;，但测试未更新。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**建议**: 更新测试以期望 &#39;pending&#39; 状态。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\\`\`\`diff</span></span>
<span class="line"><span>- expect(user.status).toBe(&#39;active&#39;);</span></span>
<span class="line"><span>+ expect(user.status).toBe(&#39;pending&#39;);</span></span>
<span class="line"><span>\\\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>*由 team-toolkit 生成*</span></span>
<span class="line"><span>\\\`\`\`</span></span></code></pre></div><p><strong>部署命令</strong></p><p>部署是最需要规范化的操作之一。手动部署时，每个人的步骤可能不同，遗漏检查项的风险很高。这个命令把部署流程固化为标准步骤，并内置了安全检查，确保没有硬编码密钥、没有已知漏洞的依赖、所有环境变量都已配置。</p><p><strong>commands/deploy.md</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: deploy</span></span>
<span class="line"><span>description: 部署应用到指定环境</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>用法：\`/deploy [environment]\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 环境</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- \`staging\` - 测试环境（默认）</span></span>
<span class="line"><span>- \`production\` - 生产环境（需要额外确认）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 部署流程</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Staging</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 运行 lint 检查</span></span>
<span class="line"><span>2. 运行单元测试</span></span>
<span class="line"><span>3. 构建 Docker 镜像</span></span>
<span class="line"><span>4. 推送到 staging 集群</span></span>
<span class="line"><span>5. 运行冒烟测试</span></span>
<span class="line"><span>6. 报告部署状态</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Production</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 确认 staging 部署成功</span></span>
<span class="line"><span>2. 确认所有测试通过</span></span>
<span class="line"><span>3. 请求用户确认</span></span>
<span class="line"><span>4. 创建 Git tag</span></span>
<span class="line"><span>5. 构建生产镜像</span></span>
<span class="line"><span>6. 蓝绿部署到生产集群</span></span>
<span class="line"><span>7. 健康检查</span></span>
<span class="line"><span>8. 报告部署状态</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 安全检查</span></span>
<span class="line"><span></span></span>
<span class="line"><span>部署前自动检查：</span></span>
<span class="line"><span>- [ ] 没有硬编码的密钥</span></span>
<span class="line"><span>- [ ] 依赖没有已知漏洞</span></span>
<span class="line"><span>- [ ] 所有环境变量已配置</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 回滚</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果部署失败，自动提供回滚命令：</span></span>
<span class="line"><span>\\\`\`\`</span></span>
<span class="line"><span>kubectl rollout undo deployment/app -n production</span></span>
<span class="line"><span>\\\`\`\`</span></span></code></pre></div><p><strong>团队能力包的 README.md</strong></p><p>README 是插件的门面。它决定了用户是否愿意安装你的插件，也是安装后的第一份参考文档。一个好的 README 应该让用户在 30 秒内了解插件能做什么、怎么安装、怎么使用。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Team Toolkit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>团队标准开发工具包，提供代码审查、测试、部署、安全扫描一体化解决方案。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 安装</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\\`\`\`bash</span></span>
<span class="line"><span>/plugin install team-toolkit@our-company</span></span>
<span class="line"><span>\\\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 功能</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 命令</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| 命令 | 说明 |</span></span>
<span class="line"><span>|------|------|</span></span>
<span class="line"><span>| \`/review [target]\` | 代码审查 |</span></span>
<span class="line"><span>| \`/test [scope]\` | 运行测试 |</span></span>
<span class="line"><span>| \`/deploy [env]\` | 部署应用 |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 代理</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| 代理 | 说明 |</span></span>
<span class="line"><span>|------|------|</span></span>
<span class="line"><span>| \`security-scanner\` | 安全漏洞扫描 |</span></span>
<span class="line"><span>| \`quick-fix\` | 快速修复小问题 |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Skills</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| Skill | 说明 |</span></span>
<span class="line"><span>|-------|------|</span></span>
<span class="line"><span>| \`react-patterns\` | React 最佳实践 |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### MCP 服务器</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| 服务器 | 说明 |</span></span>
<span class="line"><span>|--------|------|</span></span>
<span class="line"><span>| \`postgres\` | 数据库查询 |</span></span>
<span class="line"><span>| \`github\` | GitHub API |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 环境变量</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\\\`\`\`bash</span></span>
<span class="line"><span># 数据库连接（用于 postgres MCP）</span></span>
<span class="line"><span>export DATABASE_URL=&quot;postgres://...&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># GitHub Token（用于 github MCP）</span></span>
<span class="line"><span>export GITHUB_TOKEN=&quot;ghp_...&quot;</span></span>
<span class="line"><span>\\\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 更新日志</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### v2.0.0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 新增：\`/deploy\` 命令</span></span>
<span class="line"><span>- 新增：\`security-scanner\` 代理</span></span>
<span class="line"><span>- 改进：\`/review\` 输出格式</span></span>
<span class="line"><span>- 修复：Hook 脚本兼容性问题</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### v1.0.0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 初始版本</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 贡献</span></span>
<span class="line"><span></span></span>
<span class="line"><span>欢迎提交 PR！请确保：</span></span>
<span class="line"><span>1. 代码通过 lint 检查</span></span>
<span class="line"><span>2. 更新相关文档</span></span>
<span class="line"><span>3. 添加测试（如适用）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 许可证</span></span>
<span class="line"><span></span></span>
<span class="line"><span>MIT</span></span></code></pre></div><h2 id="发布与分发" tabindex="-1">发布与分发 <a class="header-anchor" href="#发布与分发" aria-label="Permalink to &quot;发布与分发&quot;">​</a></h2><p>插件开发完成后，下一步是让别人能够使用它。Claude Code 的插件分发基于 Git，插件本质上就是一个 Git 仓库。</p><p>在发布前，使用 <code>--plugin-dir</code> 参数从本地目录加载插件进行测试。这个步骤很重要，它让你在不发布的情况下验证所有组件是否正常工作。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude --plugin-dir ./team-toolkit</span></span></code></pre></div><p>加载成功后，你可以测试所有命令（ <code>/team-toolkit:review</code>、 <code>/team-toolkit:test</code>、 <code>/team-toolkit:deploy</code>），确认代理和 Skills 是否被正确识别，以及 Hooks 是否在预期时机触发。</p><p>插件发布就是推送到远程 Git 仓库。使用 Git tag 标记版本号，让用户可以安装特定版本。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd team-toolkit</span></span>
<span class="line"><span>git init</span></span>
<span class="line"><span>git add .</span></span>
<span class="line"><span>git commit -m &quot;Initial release v1.0.0&quot;</span></span>
<span class="line"><span>git tag v1.0.0</span></span>
<span class="line"><span>git remote add origin https://github.com/our-company/team-toolkit</span></span>
<span class="line"><span>git push -u origin main --tags</span></span></code></pre></div><h2 id="创建私有市场" tabindex="-1">创建私有市场 <a class="header-anchor" href="#创建私有市场" aria-label="Permalink to &quot;创建私有市场&quot;">​</a></h2><p>如果你的团队有多个插件需要管理，可以创建一个私有市场。私有市场本身也是一个 Git 仓库，包含一个 <code>marketplace.json</code> 文件，列出所有可用的插件及其版本。</p><p><strong>marketplace.json</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;name&quot;: &quot;Our Company Plugins&quot;,</span></span>
<span class="line"><span>  &quot;description&quot;: &quot;内部插件市场&quot;,</span></span>
<span class="line"><span>  &quot;plugins&quot;: [</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>      &quot;name&quot;: &quot;team-toolkit&quot;,</span></span>
<span class="line"><span>      &quot;description&quot;: &quot;团队标准开发工具包&quot;,</span></span>
<span class="line"><span>      &quot;repository&quot;: &quot;https://github.com/our-company/team-toolkit&quot;,</span></span>
<span class="line"><span>      &quot;version&quot;: &quot;2.0.0&quot;</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>      &quot;name&quot;: &quot;db-tools&quot;,</span></span>
<span class="line"><span>      &quot;description&quot;: &quot;数据库操作工具&quot;,</span></span>
<span class="line"><span>      &quot;repository&quot;: &quot;https://github.com/our-company/db-tools&quot;,</span></span>
<span class="line"><span>      &quot;version&quot;: &quot;1.2.0&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>用户可以添加你的市场，然后从中安装插件：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plugin marketplace add our-company/claude-plugins</span></span></code></pre></div><p>然后就可以安装市场中的插件：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plugin install team-toolkit@our-company</span></span></code></pre></div><p>发布新版本时，需要同步更新四个地方：</p><ol><li><p>更新 <code>plugin.json</code> 中的版本号</p></li><li><p>更新 <code>README.md</code> 中的更新日志</p></li><li><p>创建新的 Git tag</p></li><li><p>如果有私有市场，更新 <code>marketplace.json</code></p></li></ol><p>用户更新插件只需一条命令：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plugin update team-toolkit</span></span></code></pre></div><h2 id="plugins最佳实践" tabindex="-1">Plugins最佳实践 <a class="header-anchor" href="#plugins最佳实践" aria-label="Permalink to &quot;Plugins最佳实践&quot;">​</a></h2><p>经过前面的实战，让我们提炼几条插件设计的核心原则。</p><p><strong>单一职责</strong>，一个插件应该解决一类问题。不要创建万能插件，这与软件工程中的单一职责原则是同一个道理：职责越集中，维护越容易，复用越灵活。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>好的：</span></span>
<span class="line"><span>- db-tools — 数据库操作</span></span>
<span class="line"><span>- git-workflow — Git 工作流</span></span>
<span class="line"><span>- security-check — 安全检查</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不好的：</span></span>
<span class="line"><span>- everything-plugin — 什么都有</span></span></code></pre></div><p><strong>渐进式复杂度</strong>，从简单开始，逐步添加功能。不要试图在第一个版本就做到完美。每个版本解决一个明确的问题，让用户有时间适应和反馈。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v1.0.0: 基础的代码审查命令</span></span>
<span class="line"><span>v1.1.0: 添加安全扫描代理</span></span>
<span class="line"><span>v1.2.0: 添加 React Skill</span></span>
<span class="line"><span>v2.0.0: 添加 MCP 集成</span></span></code></pre></div><p><strong>最小权限</strong>，只请求必要的工具权限。一个只做分析的代理不需要 Write 和 Edit 工具，一个只做查询的 MCP 不需要写入权限。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 只需要读取的代理</span></span>
<span class="line"><span>tools: Read, Grep, Glob</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 不要这样（权限过大）</span></span>
<span class="line"><span>tools: Read, Write, Edit, Bash, Task</span></span></code></pre></div><p><strong>文档是第一优先级</strong>，没有文档的插件是没有价值的。你可能觉得代码和配置“不言自明“，但安装你插件的用户不这么想。他们需要知道每个命令怎么用、每个环境变量什么意思、出了问题怎么排查。文档中 <strong>必须包含</strong> 安装方法、每个命令的用法和示例、环境变量说明、更新日志； <strong>最好包含</strong> 使用场景、常见问题和贡献指南。</p><p><strong>版本管理</strong>——使用语义化版本（Semantic Versioning），让用户清楚每次更新的影响范围。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/7172f9ea57cdb5796da29df821ff573a.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/7172f9ea57cdb5796da29df821ff573a.jpg" alt="图片"></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/272028995ed06998f0f10ea3f3aa8f91.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/272028995ed06998f0f10ea3f3aa8f91.jpg" alt="图片"></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/2c3e8a760f037ecebbb451ed24f434be.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/2c3e8a760f037ecebbb451ed24f434be.png" alt="图片"></a></p><h2 id="总结一下" tabindex="-1">总结一下 <a class="header-anchor" href="#总结一下" aria-label="Permalink to &quot;总结一下&quot;">​</a></h2><p>这一讲，我们学习了 Claude Code 插件系统的完整内容，并构建了一个“团队能力包”插件。</p><p>插件是 Claude Code 扩展能力的标准打包方式。它可以包含斜杠命令（快捷操作）、子代理（专业助手）、Skills（领域知识）、Hooks（自动化行为）和 MCP 服务器（外部工具连接）。这些组件打包在一起，用户只需一条命令就能安装全部功能。</p><p>插件的目录结构是固定的： <code>.claude-plugin/plugin.json</code> 是必需的元数据文件， <code>commands/</code>、 <code>agents/</code>、 <code>skills/</code>、 <code>hooks/</code> 目录存放各类组件， <code>.mcp.json</code> 配置外部工具连接。所有组件目录都在插件根目录下，只有 <code>plugin.json</code> 在 <code>.claude-plugin/</code> 内。</p><p>发布插件就是推送 Git 仓库。你可以发布到公开的社区市场，也可以创建私有市场供团队使用。用户通过 <code>/plugin marketplace add</code> 添加市场，通过 <code>/plugin install</code> 安装插件。</p><p>设计插件时要遵循单一职责、最小权限、文档优先的原则。一个好的插件应该专注于解决一类问题，只请求必要的权限，并提供完整的使用文档。版本管理使用语义化版本，让用户清楚每次更新的影响。</p><p>回顾这一讲的内容，你会发现一个有趣的模式。Commands、Agents、Skills、Hooks、MCP，这些我们在前 20 讲中逐一学习的独立组件，在插件系统中被统一成了一个整体。这不是简单的“打包”，而是一种系统级的思维转变：从“我有一堆好用的工具”到“我有一个可安装的解决方案”。这个转变的意义在于，它让你的工程经验变得可传递、可版本化、可持续迭代。把知识变成资产，把重复变成复用，把个人经验变成团队能力。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>回顾你日常工作中最耗时的重复任务，哪些可以用本课程学到的技术自动化？试着列出三个具体场景，并说明你会用哪些组件（Commands、Agents、Skills、Hooks、MCP）来实现。</p></li><li><p>如果你要为团队创建一个插件，你会包含哪些组件？为什么？请给出完整的 <code>plugin.json</code> 和目录结构设计。</p></li><li><p>插件的“单一职责”原则在实践中如何把握？如果团队的代码审查、测试、部署高度耦合，应该做成一个插件还是三个插件？请分析利弊。</p></li><li><p>Claude Code 的能力边界在哪里？有哪些任务你认为仍然应该由人类完成，而不应该被封装进插件？</p></li></ol><h2 id="课程总结-从使用者到驾驭者" tabindex="-1">课程总结：从使用者到驾驭者 <a class="header-anchor" href="#课程总结-从使用者到驾驭者" aria-label="Permalink to &quot;课程总结：从使用者到驾驭者&quot;">​</a></h2><p>恭喜你完成了《Claude Code 工程化实战》全部内容！</p><p>让我们回顾这段旅程。</p><p><strong>第一部分：基础篇（第 1-2 讲）</strong></p><p>我们从 Claude Code 全景导览开始，理解了它不只是命令行助手，而是可扩展的 AI Agent 框架。然后学习了 CLAUDE.md 记忆系统，让 Claude 记住项目规范和团队约定。</p><p><strong>第二部分：子代理专题（第 3-8 讲）</strong></p><p>我们深入学习了子代理的核心概念，把“一个大脑”拆成多个“专职岗位”。通过代码审查员、测试运行器、日志分析器、多视角探索、Bug 修复流水线和 Agent Teams 等实战项目，掌握了隔离执行、权限边界和上下文管理。</p><p><strong>第三部分：Skills 技能系统（第 9-14 讲）</strong></p><p>我们理解了 SKILL.md 的触发机制——description 不是说明文档，而是触发器。学习了渐进式披露架构，用目录页、章节、附录三层结构把 token 利用率提升 98%。通过 API 生成器等项目，掌握了构建完整领域能力包的方法。最后，我们见证了 Skills 从 Claude Code 的产品特性出圈成为行业开放标准的过程。</p><p><strong>第四部分：核心组件和机制（第 15-18 讲）</strong></p><p>我们学习了 Hooks 实现事件驱动自动化（基础篇和高级篇），MCP 连接数据库、API 和第三方服务。这些扩展机制让 Claude Code 成为一个可编程、可定制的平台。</p><p><strong>第五部分：生产化与工程化（第 19-23讲）</strong></p><p>我们学习了 Headless 模式让 Claude 在 CI/CD 中无人值守运行，Agent SDK 让你用代码驱动 AI 执行任务（基础篇和高级篇），最后用 Plugins 把所有能力打包成可复用的资产。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/3b436bbc7af58888c734e83fe8c39c63.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/966900/3b436bbc7af58888c734e83fe8c39c63.jpg" alt="图片"></a></p><p><strong>你现在掌握的能力已经有这么多了！</strong></p><ul><li><p><strong>Memory系统</strong>：让 Claude 理解你的项目</p></li><li><p><strong>SubAgents</strong>：分而治之，各司其职</p></li><li><p><strong>Skills</strong>：领域知识，按需加载</p></li><li><p><strong>Commands</strong>：团队标准，一键执行</p></li><li><p><strong>Hooks</strong>：自动化行为，无需手动</p></li><li><p><strong>MCP</strong>：连接万物，扩展边界</p></li><li><p><strong>Headless</strong>：自动运行，无人值守</p></li><li><p><strong>Rules</strong>：规则权限，有章可循</p></li><li><p><strong>Agent SDK</strong>：代码驱动，完全掌控</p></li><li><p><strong>Plugins</strong>：打包分发，复用共享</p></li></ul><p><strong>你已经从 Claude Code 的使用者成长为驾驭者。</strong></p><p>这门课程教给你的是框架和模式，真正的掌握来自实践。</p><p>佳哥在这里建议你：</p><ol><li><p><strong>从小处开始</strong>：做一个又一个项目，体验Claude Code的价值</p></li><li><p><strong>逐步深入</strong>：遇到重复任务，尝试用子代理或 Skill 解决</p></li><li><p><strong>持续积累</strong>：把好用的配置打包成插件，形成你的工具箱</p></li><li><p><strong>分享交流</strong>：把你的插件和心得分享给团队或社区（咱们的群），在反馈中进步</p></li></ol><p>AI 正在重塑软件开发的方式。Claude Code 不是要替代开发者，而是要 <strong>增强</strong> 开发者。它处理重复，你做创造；它执行任务，你做决策；它是工具，你是主人。 <strong>人机协作的未来已经到来，而咱们已经准备好驾驭它。</strong></p><p>感谢你的学习，祝你在 AI 辅助开发的道路上越走越远。不过还没完呢，我们还有结束语和20道测试题，别忘了看，也别忘了给佳哥和你自己点赞！</p>`,166)])])}const h=n(e,[["render",i]]);export{g as __pageData,h as default};
